function richText(container,text){const links=/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)|(https?:\/\/[^\s<>]+)|\*\*([^*]+)\*\*|`([^`]+)`/g;let offset=0;for(const m of text.matchAll(links)){container.append(document.createTextNode(text.slice(offset,m.index)));if(m[4]||m[5])container.append(el(m[4]?'strong':'code','',m[4]||m[5]));else{const a=el('a','',m[1]||m[3]);a.href=m[2]||m[3];a.target='_blank';a.rel='noopener noreferrer';container.append(a);}offset=m.index+m[0].length;}container.append(document.createTextNode(text.slice(offset)));}
function message(role,text,sources,error=false){$('welcome').hidden=true;const article=el('article','chat-message '+role+(error?' error':''));article.append(el('strong','',language==='en'?(role==='user'?'You':'Paoween'):(role==='user'?'คุณ':'เป๋าวีน')));const p=el('p');richText(p,String(text));article.append(p);if(sources)article.append(el('div','chat-evidence',language==='en'?'Based on '+sources.transactions+' transactions · '+sources.tasks+' review tasks · '+(sources.scope.year==='all'?'all years':sources.scope.year)+' / '+(sources.scope.month==='all'?'all months':monthLabel(Number(sources.scope.month)-1)):'อ้างอิงบัญชี '+sources.transactions+' รายการ · งานตรวจ '+sources.tasks+' งาน · '+(sources.scope.year==='all'?'ทุกปี':Number(sources.scope.year)+543)+' / '+(sources.scope.month==='all'?'ทุกเดือน':monthLabel(Number(sources.scope.month)-1))));$('chat-log').append(article);$('conversation').scrollTop=$('conversation').scrollHeight;}
function controls(value){busy=value;$('send').disabled=value;$('reset').disabled=value;$('voice').disabled=value;$('attach-receipt').disabled=value;$('remove-receipt').disabled=value;$('year').disabled=value;$('month').disabled=value;$('refresh').disabled=value;document.querySelectorAll('[data-prompt]').forEach(b=>b.disabled=value);$('job-row').hidden=!value;$('stop-job').disabled=false;}
function draft(text){$('command').value=text;$('command').focus();$('command').dispatchEvent(new Event('input'));}
function showProposal(p){const box=$('proposal');box.replaceChildren();box.hidden=!p;if(!p)return;state('Approval','รอคุณตรวจและยืนยัน');const a=p.action,kind=language==='en'?{expense:'expense',income:'income',investment:'investment',transfer:'transfer between your own accounts'}:{expense:'รายจ่าย',income:'รายรับ',investment:'การลงทุน',transfer:'โอนระหว่างบัญชีตัวเอง'};box.append(el('h3','',language==='en'?'Review and confirm before saving':'ตรวจให้ตรงใจ แล้วค่อยบันทึก'));const preview=el('pre');preview.textContent=a.kind==='review_task'?(language==='en'?'Review note for task ':'คำอธิบายงาน ')+a.task_id+'\n'+a.note:(language==='en'?'Add ':'เพิ่ม')+(kind[a.transaction_type]||a.transaction_type)+' · '+a.date+'\n'+a.description+'\n'+baht(a.amount_thb)+' · '+categoryLabel(a.category)+(a.action?' · '+(language==='en'?(a.action==='Buy'?'Buy':'Sell'):(a.action==='Buy'?'ซื้อ':'ขาย')):'')+(a.tax_category?(language==='en'?'\nSalary tax follow-up · gross amount and 50 bis required':'\nติดตามเงินเดือนสำหรับภาษี · รอยอด gross และ 50 ทวิ'):'' );const evidence=p.receipts|| (p.receipt?[p.receipt]:[]);if(evidence.length)preview.textContent+='\n'+(language==='en'?'Evidence':'หลักฐาน')+' '+evidence.length+' '+(language==='en'?'images':'รูป')+': '+evidence.map(x=>x.name).join(', ');if(a.data_quality_flag)preview.textContent+='\n'+(language==='en'?'Needs review: ':'รอตรวจ: ')+a.data_quality_flag.replace(/^needs_review:\s*/,'');const yes=el('button','primary',language==='en'?'Confirm and save this item':'ยืนยันบันทึกรายการนี้'),no=el('button','secondary',language==='en'?'Skip for now':'ข้ามก่อน'),edit=el('button','secondary',language==='en'?'Edit proposal':'แก้ไขแผน');yes.type=no.type=edit.type='button';edit.onclick=()=>{box.hidden=true;state('Idle','แก้รายละเอียดก่อนส่งใหม่');draft(language==='en'?'Prepare a revised proposal (do not save yet): date '+a.date+', type '+a.transaction_type+', description '+a.description+', amount '+a.amount_thb+' THB, category '+a.category+(a.action?', action '+a.action:''):'ช่วยเตรียมแผนบันทึกใหม่ (ยังไม่บันทึก): วันที่ '+a.date+' ประเภท '+a.transaction_type+' รายละเอียด '+a.description+' ยอด '+a.amount_thb+' บาท หมวด '+a.category+(a.action?' action '+a.action:''));};no.onclick=()=>{box.hidden=true;state('Idle','พร้อมช่วยคิด');};yes.onclick=async()=>{controls(true);yes.disabled=no.disabled=edit.disabled=true;$('job-status').textContent=language==='en'?'Checking the latest data and saving as confirmed':'กำลังตรวจข้อมูลล่าสุดและบันทึกตามที่คุณยืนยัน';state('Read','กำลังตรวจและบันทึก');try{const result=await api('/approve',{session,proposal_id:p.id});message('assistant',result.answer);box.hidden=true;state('Done','บันทึกเรียบร้อยแล้ว');await loadContext();}catch(e){message('assistant',e.message,null,true);box.hidden=true;state('Error','ยังบันทึกไม่ได้');}finally{controls(false);}};box.append(preview,yes,edit,no);}
function pillar(){return({spending:'spending',transactions:'spending',investment:'investment',tax:'tax',review:'overview',shopping:'shopping',overview:'overview'})[currentView];}
function receiptError(text){$('receipt-error').textContent=text;$('receipt-error').hidden=!text;}
function clearReceipt(){receiptSelection++;for(const item of selectedReceipts)URL.revokeObjectURL(item.url);selectedReceipts=[];$('receipt-preview').hidden=true;$('receipt-items').replaceChildren();$('receipt-file').value='';receiptError('');}
$('attach-receipt').onclick=()=>$('receipt-file').click();
$('remove-receipt').onclick=()=>{clearReceipt();$('command').focus();};
function renderReceiptPreview(){const items=$('receipt-items');items.replaceChildren();$('receipt-count').textContent=language==='en'?'Attached '+selectedReceipts.length+' images':'แนบ '+selectedReceipts.length+' รูป';$('receipt-preview').hidden=!selectedReceipts.length;selectedReceipts.forEach((item,index)=>{const card=el('div','receipt-item'),img=el('img'),meta=el('div','receipt-item-meta'),name=el('strong','',item.name),size=el('span','',Math.ceil(item.size/1024)+' KB'),remove=el('button','secondary','เอาออก');img.src=item.url;img.alt=(language==='en'?'Preview ':'ตัวอย่าง ')+item.name;remove.type='button';remove.setAttribute('aria-label',language==='en'?'Remove '+item.name:'เอารูป '+item.name+' ออก');remove.onclick=()=>{URL.revokeObjectURL(item.url);selectedReceipts.splice(index,1);renderReceiptPreview();};meta.append(name,size);card.append(img,meta,remove);items.append(card);});}
$('receipt-file').onchange=async()=>{const files=Array.from($('receipt-file').files||[]);$('receipt-file').value='';if(!files.length)return;const selection=++receiptSelection;let errors=[];for(const file of files){if(selectedReceipts.length>=5){errors.push(language==='en'?'Up to 5 images are allowed':'แนบได้สูงสุด 5 รูป');break;}if(!['image/jpeg','image/png'].includes(file.type)||file.size>8*1024*1024||!file.size){errors.push(file.name+(language==='en'?': Choose JPG/PNG up to 8 MB':': เลือก JPG/PNG ขนาดไม่เกิน 8 MB'));continue;}if(selectedReceipts.reduce((sum,item)=>sum+item.size,0)+file.size>25*1024*1024){errors.push(language==='en'?'All images together must be 25 MB or less':'รูปทั้งหมดรวมกันต้องไม่เกิน 25 MB');continue;}const url=URL.createObjectURL(file);try{const preview=new Image();await new Promise((resolve,reject)=>{preview.onload=resolve;preview.onerror=()=>reject(Error('เปิดรูปไม่ได้'));preview.src=url;});if(preview.naturalWidth*preview.naturalHeight>25000000)throw Error('ภาพใหญ่เกิน 25 ล้านพิกเซล');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('อ่านไฟล์ไม่สำเร็จ'));reader.readAsDataURL(file);});if(selection!==receiptSelection){URL.revokeObjectURL(url);return;}if(selectedReceipts.some(item=>item.name===file.name&&item.base64===encoded)){URL.revokeObjectURL(url);errors.push(file.name+(language==='en'?': Already selected':': เลือกรูปนี้แล้ว'));continue;}selectedReceipts.push({name:file.name,mime:file.type,base64:encoded,size:file.size,url});}catch(e){URL.revokeObjectURL(url);errors.push(file.name+': '+e.message);}}renderReceiptPreview();receiptError(errors.join(' · '));$('command').focus();};
 $('command-form').onsubmit=async event=>{event.preventDefault();if(busy)return;const receipts=selectedReceipts.map(({name,mime,base64})=>({name,mime,base64})),text=$('command').value.trim()||(receipts.length?language==='en'?'Read all receipts and prepare items for my review. Do not save anything yet.':'ช่วยอ่านสลิปทั้งหมดและเตรียมรายการให้ตรวจ ก่อนยืนยันบันทึก':'');if(!text)return;const token=generation;controls(true);showProposal(null);message('user',text+(receipts.length?'\nแนบรูป '+receipts.length+' รูป: '+receipts.map(x=>x.name).join(', '):''));if(receipts.length){for(const receipt of receipts){const img=el('img','chat-receipt');img.src='data:'+receipt.mime+';base64,'+receipt.base64;img.alt='สลิป '+receipt.name;$('chat-log').lastElementChild.append(img);}}$('command').value='';$('command').style.height='auto';state('Read','กำลังอ่านข้อมูล');$('job-status').textContent='กำลังเริ่มงาน อ่านบัญชีตามช่วงที่เลือก';try{if(!session)session=(await api('/session',{})).session;await api('/chat',{session,message:text,pillar:pillar(),scope:scope(),receipts,language});if(receipts.length)clearReceipt();let finished=false;for(let i=0;i<150;i++){const job=await api('/job?session='+encodeURIComponent(session));if(token!==generation)return;$('job-status').textContent=job.stage||'กำลังประมวลผล';if(job.status==='done'){message('assistant',job.answer,job.sources);if(job.view&&Object.hasOwn(titles,job.view.name)){if([...$('year').options].some(o=>o.value===job.view.year))$('year').value=job.view.year;else if(job.view.year!=='all'){$('year').append(new Option(String(Number(job.view.year)+543),job.view.year));$('year').value=job.view.year;}$('month').value=job.view.month;currentView=job.view.name;await loadContext();openView(job.view.name,true);}state('Talk','ตอบแล้ว พร้อมคุยต่อ');showProposal(job.proposal);if(!job.proposal)setTimeout(()=>{if(!busy&&currentState==='Talk')state('Idle','พร้อมช่วยคิด');},2200);finished=true;break;}if(job.status==='cancelled'){message('assistant','หยุดงานแล้ว ยังไม่มีการบันทึกบัญชี');state('Idle','พร้อมช่วยคิด');finished=true;break;}if(job.status==='error')throw Error(job.error);state(job.stage?.includes('อ่าน')?'Read':'Think',job.stage?.includes('อ่าน')?'กำลังอ่านข้อมูล':'กำลังคิดให้รอบคอบ');await new Promise(resolve=>setTimeout(resolve,2000));}if(!finished)throw Error('งานใช้เวลานานกว่าที่หน้าเว็บรอได้ กดเริ่มบทสนทนาใหม่แล้วลองอีกครั้ง');}catch(e){message('assistant',e.message,null,true);state('Error','ยังทำงานไม่สำเร็จ');}finally{controls(false);$('command').focus();}};
$('command').oninput=()=>{$('command').style.height='auto';$('command').style.height=Math.min($('command').scrollHeight,130)+'px';};$('command').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('command-form').requestSubmit();}};
