// Voice is a user-triggered browser transcription draft. It never submits a transaction.
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;let recognition=null,voiceAccepted=false;
function voiceError(text){$('input-help').textContent=text;state('Idle','พร้อมช่วยคิด');$('voice').classList.remove('listening');$('voice').setAttribute('aria-label','ใช้เสียงพิมพ์คำสั่ง');}
function startVoice(){try{recognition=new Recognition();recognition.lang=language==='en'?'en-US':'th-TH';recognition.interimResults=false;recognition.maxAlternatives=1;recognition.onstart=()=>{state('Listen','กำลังฟังคุณ');$('voice').classList.add('listening');$('voice').setAttribute('aria-label','หยุดฟังเสียง');$('input-help').textContent='กำลังฟัง… กดไมค์อีกครั้งเพื่อหยุด';};recognition.onresult=e=>{draft((($('command').value.trim()+' ').trimStart())+e.results[0][0].transcript);$('input-help').textContent='ตรวจข้อความที่ถอดได้ แล้วกดส่งเอง';};recognition.onerror=e=>voiceError(({ 'not-allowed':'เบราว์เซอร์ไม่ได้รับอนุญาตให้ใช้ไมค์ ใช้พิมพ์ได้เลย','no-speech':'ยังไม่ได้ยินเสียง ลองใหม่หรือพิมพ์แทน','network':'บริการถอดเสียงเชื่อมต่อไม่ได้ ใช้พิมพ์ต่อได้','audio-capture':'ไม่พบไมโครโฟน ใช้พิมพ์ต่อได้'})[e.error]||'ถอดเสียงไม่สำเร็จ ใช้พิมพ์ต่อได้');recognition.onend=()=>{$('voice').classList.remove('listening');$('voice').setAttribute('aria-label','ใช้เสียงพิมพ์คำสั่ง');if(!busy)state('Idle','พร้อมช่วยคิด');recognition=null;};recognition.start();}catch{voiceError('เบราว์เซอร์นี้เริ่มถอดเสียงไม่ได้ ใช้พิมพ์ต่อได้');}}
$('voice').onclick=()=>{if(!Recognition){$('input-help').textContent='เบราว์เซอร์นี้ไม่รองรับถอดเสียง ใช้พิมพ์คำสั่งได้ตามปกติ';return;}if(recognition){recognition.stop();return;}if(voiceAccepted){startVoice();return;}$('voice-consent').showModal();};$('voice-consent').addEventListener('close',()=>{if($('voice-consent').returnValue==='allow'){voiceAccepted=true;startVoice();}});
if(!Recognition)$('voice').title='เบราว์เซอร์นี้ไม่รองรับถอดเสียง ใช้พิมพ์แทนได้';
