async function initData(){for(let i=1;i<=12;i++)$('month').append(new Option(monthLabel(i-1),String(i).padStart(2,'0')));try{const all=await api('/context?year=all&month=all');const years=[...new Set([...all.transactions.map(r=>r.date.slice(0,4)),...all.tax_records.map(r=>String(Number(r.tax_year)-543))])].filter(y=>/^[12]\d{3}$/.test(y)).sort().reverse();for(const y of years)$('year').append(new Option(language==='en'?y:String(Number(y)+543),y));const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric'}).format(new Date());if(years.includes(today))$('year').value=today;currentView=Object.hasOwn(titles,location.hash.slice(1))?location.hash.slice(1):'overview';await loadContext();}catch(e){$('panel').replaceChildren(el('div','empty',e.message));$('connection').classList.add('offline');$('connection').lastChild.textContent=language==='en'?' Not connected':' ยังไม่เชื่อมต่อ';}}
