// Three.js and GLB are served locally. A rendered still remains as the fallback.
async function initCharacter(){try{const THREE=await import('three'),{GLTFLoader}=await import('./assets/vendor/GLTFLoader.js');const container=$('model'),scene=new THREE.Scene(),renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;container.append(renderer.domElement);renderer.domElement.setAttribute('aria-hidden','true');renderer.domElement.addEventListener('webglcontextlost',event=>{event.preventDefault();$('model-fallback').hidden=false;renderer.domElement.hidden=true;$('motion').hidden=true;});const camera=new THREE.OrthographicCamera(-2,2,2,-2,.1,30);camera.position.set(3,1.9,10);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight(0xfff7e4,0x768b68,2.5));const key=new THREE.DirectionalLight(0xffe9cb,3);key.position.set(-3,5,6);scene.add(key);const fill=new THREE.DirectionalLight(0xffffff,1.3);fill.position.set(4,2,-1);scene.add(fill);const gltf=await new GLTFLoader().loadAsync('./assets/paoween/paoween.glb');const model=gltf.scene,bounds=new THREE.Box3().setFromObject(model),center=bounds.getCenter(new THREE.Vector3());model.position.sub(center);scene.add(model);const mixer=new THREE.AnimationMixer(model),actions=new Map(gltf.animations.map(clip=>[clip.name,mixer.clipAction(clip)]));let active=null;function pose(name){const next=actions.get(name)||actions.get('Idle');if(next&&next!==active){next.reset().setEffectiveWeight(1).play();if(active)active.crossFadeTo(next,.3,true);active=next;}if(paused){mixer.update(.35);renderer.render(scene,camera);}}animateCharacter=pose;pose(currentState);$('model-fallback').hidden=true;const clock=new THREE.Clock();function resize(){const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);const half=1.95,aspect=w/h;camera.left=-half*aspect;camera.right=half*aspect;camera.top=half;camera.bottom=-half;camera.updateProjectionMatrix();renderer.render(scene,camera);}new ResizeObserver(resize).observe(container);resize();function frame(){requestAnimationFrame(frame);const delta=Math.min(clock.getDelta(),.05);if(document.hidden)return;if(!paused){mixer.update(delta);renderer.render(scene,camera);}}frame();$('motion').onclick=()=>{paused=!paused;$('motion').setAttribute('aria-pressed',String(paused));$('motion').setAttribute('aria-label',paused?(language==='en'?'Play animation':'เล่นภาพเคลื่อนไหว'):(language==='en'?'Pause animation':'หยุดภาพเคลื่อนไหว'));$('motion').innerHTML=paused?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 10 7-10 7Z"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg>';};$('motion').setAttribute('aria-pressed',String(paused));$('motion').setAttribute('aria-label',paused?(language==='en'?'Play animation':'เล่นภาพเคลื่อนไหว'):(language==='en'?'Pause animation':'หยุดภาพเคลื่อนไหว'));matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',event=>{paused=event.matches;$('motion').setAttribute('aria-pressed',String(paused));});}catch(error){$('motion').hidden=true;console.warn('Paoween 3D unavailable; using rendered character still.',error);}}
initCharacter();

